'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='aura-space-v1';let state={moods:[],entries:[],sessions:[],plans:[],persist:false},storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&Array.isArray(saved.moods)&&Array.isArray(saved.entries)&&Array.isArray(saved.sessions)&&Array.isArray(saved.plans))state={...state,...saved};}catch{storageAvailable=false;}
function save(){if(window.auraPersist){window.auraPersist();return;}if(state.persist)try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;toast('Browser storage is unavailable. Keep this tab open or export your work.');}};
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
const niceDate=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'}), stamp=()=>new Date().toISOString();
$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});
const exercises=[
{id:'thought',icon:'◈',name:'Untangle a thought',type:'CBT-informed',time:'8–12 min',desc:'Separate what happened from what your mind made it mean.',steps:[['What happened?','Describe one specific situation, as a camera might record it.'],['What went through your mind?','What did this situation seem to say about you, other people, or the future?'],['What did you feel?','Name the emotions, body sensations, and their intensity from 0–10.'],['What supports that interpretation?','List observable facts. It is okay if there is real evidence of a problem.'],['What might be missing?','Consider uncertainty, exceptions, or another plausible explanation.'],['What is a balanced way to see it?','Aim for an accurate, compassionate interpretation—not forced positivity.'],['What could you do next?','Choose one safe, manageable action. How strong is the feeling now?']]},
{id:'activation',icon:'☀',name:'Find one small step',type:'Behavioural activation',time:'5–8 min',desc:'Make room for something meaningful, even when motivation is low.',steps:[['How have your days been feeling?','What have you stopped doing, or found harder to start?'],['What matters to you here?','Consider connection, care, curiosity, accomplishment, or rest.'],['What is a very small action?','Pick something realistic for your current energy. Two minutes can count.'],['When and where will you try it?','Be specific. Make it smaller if it already feels overwhelming.'],['What might get in the way?','Plan a gentler alternative and a way to make starting easier.']]},
{id:'values',icon:'✧',name:'Come back to what matters',type:'Acceptance & values',time:'6–10 min',desc:'Find a direction while allowing difficult feelings to be here.',steps:[['What is taking up space in your mind?','Notice a thought or feeling without needing to solve it immediately.'],['Can you name it with a little distance?','Try: “I’m noticing the thought that…” or “There is sadness here.”'],['What do you want to stand for?','Choose a quality of action, such as kindness, honesty, learning, or courage.'],['What is in your control today?','You cannot guarantee an outcome. What small action would express that value?'],['How will you make room for discomfort?','What could help you act gently without waiting for the feeling to disappear?']]},
{id:'problem',icon:'⌘',name:'Make a workable plan',type:'Problem-solving',time:'8–12 min',desc:'Turn an overwhelming problem into a practical next move.',steps:[['What is the specific problem?','Choose one issue you can influence. Separate it from worries you cannot control.'],['What would a useful improvement look like?','Define a small, realistic outcome rather than a perfect solution.'],['What are three possible approaches?','Include doing a smaller part, asking for help, or changing the timing.'],['What are the benefits and drawbacks?','Consider effort, resources, safety, and what is under your control.'],['Which approach will you try?','Specify the first action, when you will do it, and who could help.'],['When will you review it?','Decide how you will learn from the attempt and adjust.']]},
{id:'pattern',icon:'↝',name:'Understand a recurring loop',type:'Guided reflection',time:'8–12 min',desc:'Notice triggers, responses, and what keeps a pattern going.',steps:[['What keeps happening?','Choose a recent example of a recurring difficulty.'],['What happened just before it?','Notice the situation, your energy, stress, and any earlier events.'],['What meaning did you give it?','What did you fear, expect, or need in that moment?'],['How did you respond?','Include actions, urges, body sensations, and things you avoided.'],['What happened in the short and longer term?','Did the response help briefly but create another difficulty later?'],['What is one place you could try a different response?','Treat this as an experiment, not a judgment about your character.']]},
{id:'compassion',icon:'♡',name:'A kinder inner voice',type:'Self-compassion',time:'4–7 min',desc:'Respond to a difficult moment without adding self-criticism.',steps:[['What are you finding difficult?','Describe it in your own words. You do not need to justify your feelings.'],['What is your inner critic saying?','Notice the words without assuming they are facts. You can skip this if it feels unhelpful.'],['What would you say to someone you care about?','Try a kind, believable response that still acknowledges the difficulty.'],['What do you need right now?','Choose one small act of care, a boundary, or a request for support.']]}
];
let selectedMood=0,flow=null,breathTimer=null,breathSeconds=0;
const heading=(tag,title,sub)=>`<div class="intro"><div><p class="eyebrow">${tag}</p><h1>${title}</h1><p class="sub">${sub}</p></div><div class="flower" aria-hidden="true">${window.auraCatSymbol?window.auraCatSymbol():''}</div></div>`;
const toolCard=x=>`<a class="card tool-card" href="#exercise/${x.id}"><span class="icon" aria-hidden="true">${x.icon}</span><h3>${x.name}</h3><p>${x.desc}</p><span class="tag">${x.type} &nbsp; · &nbsp; ${x.time} ↗</span></a>`;
function home(){const today=new Date().toDateString(),count=state.moods.filter(x=>new Date(x.date).toDateString()===today).length;return heading('TAKE A MOMENT FOR YOURSELF','A little room to breathe.','You don’t have to figure everything out today. Let’s start with where you are.')+`<div class="hero-grid"><section class="card mood-card"><h2>How are you feeling right now?</h2><p class="small">There’s no right answer. Just your answer.</p><div class="moods">${['Very low','Low','Somewhere between','Okay','Good'].map((x,i)=>`<button class="mood ${selectedMood===i+1?'selected':''}" data-mood="${i+1}" aria-pressed="${selectedMood===i+1}"><span class="face">${['⌢','﹏','−','⌣','◡'][i]}</span>${x}</button>`).join('')}</div><button class="primary" data-action="mood">Save check-in &nbsp; ↗</button><p class="small" style="margin:12px 0 0">${count?'You have checked in today. You can check in again.':'A small pause to notice how things feel.'}</p></section><section class="card feature"><p class="eyebrow">ONE THING AT A TIME</p><h2>Let’s make a little<br>sense of things.</h2><p class="small">A guided space to untangle what happened, how it felt, and what you need.</p><a class="primary" href="#sessions">Start a reflection &nbsp; ↗</a><div class="orbit" aria-hidden="true"></div></section></div><div class="section-head"><h2>Something to meet you where you are</h2><a class="text-link" href="#tools">Explore all practices ↗</a></div><div class="grid3">${[exercises[0],exercises[1],exercises[2]].map(toolCard).join('')}</div><div class="quote"><span aria-hidden="true">✧</span><p>You can take the next step without seeing the whole path.<small>A gentle reminder, wherever you are today.</small></p></div>`;}
function sessions(){return heading('WORK THROUGH SOMETHING','Start with what’s here.','Choose a direction. These are guided written exercises, not a live conversation or clinical assessment.')+`<div class="grid3">${exercises.map(toolCard).join('')}</div><div class="notice">If you’re overwhelmed, you can pause at any time. Try grounding first, or reach out to someone you trust. <a href="#support">Find human support →</a></div>`;}
function tools(){return heading('THE PRACTICE LIBRARY','Skills for the everyday.','Practical tools to explore at your own pace. Use what fits; leave what doesn’t.')+`<div class="grid3"><a class="card tool-card" href="#ground"><span class="icon">❋</span><h3>Return to the present</h3><p>A gentle sensory grounding practice. Keep your eyes open if that feels better.</p><span class="tag">GROUNDING · 2–5 MIN ↗</span></a><a class="card tool-card" href="#breathe"><span class="icon">◌</span><h3>A slower moment</h3><p>An optional breathing rhythm with no breath holds. Stop if it feels uncomfortable.</p><span class="tag">SETTLING · 1 MIN ↗</span></a><a class="card tool-card" href="#plan"><span class="icon">↗</span><h3>Plan one meaningful action</h3><p>Make a small commitment and return to notice what you learned.</p><span class="tag">ACTION PLANNING · 3 MIN ↗</span></a>${exercises.map(toolCard).join('')}</div>`;}
function exercise(id){const ex=exercises.find(x=>x.id===id);if(!ex)return '<h1>Practice not found</h1><a href="#tools">Back to the library</a>';if(!flow||flow.id!==id)flow={id,index:0,answers:Array(ex.steps.length).fill(''),finished:false};if(flow.finished)return summary(ex);const step=ex.steps[flow.index];return `<div class="narrow"><a class="text-link" href="#sessions">← All reflections</a><p class="eyebrow">${ex.type} · ${ex.time}</p><h1>${ex.name}</h1><div class="step-track" aria-hidden="true">${ex.steps.map((_,i)=>`<span class="${i<=flow.index?'on':''}"></span>`).join('')}</div><div class="card"><div class="step-count">STEP ${flow.index+1} OF ${ex.steps.length}</div><h2 class="prompt">${step[0]}</h2><p class="small">${step[1]}</p><label for="answer">Your reflection (optional)</label><textarea id="answer" maxlength="10000" placeholder="Take your time. A few words are enough…">${esc(flow.answers[flow.index])}</textarea><div class="actions"><button class="primary" data-action="next">${flow.index===ex.steps.length-1?'Review my reflection':'Continue'} ↗</button>${flow.index?'<button class="secondary" data-action="back">Back</button>':''}<a class="secondary" href="#ground">Take a grounding break</a></div></div><p class="small" style="margin-top:16px">This exercise does not interpret or diagnose you. You decide what fits. Unsaved answers remain only while this tab is open.</p></div>`;}
function summary(ex){return `<div class="narrow">${heading('YOUR REFLECTION','A little more understanding.','Read back what you noticed. You can edit your answers or save this to your journal.')}<div class="card">${ex.steps.map((s,i)=>`<div class="summary-row"><strong>${s[0]}</strong>${esc(flow.answers[i]||'Skipped')}</div>`).join('')}<label for="takeaway">What do you want to take with you?</label><textarea id="takeaway" placeholder="One insight, a small next step, or something to return to…" maxlength="10000"></textarea><div class="actions"><button class="primary" data-action="finish">Save reflection</button><button class="secondary" data-action="edit">Edit answers</button></div></div></div>`;}
function journal(){return heading('YOUR JOURNAL','Make space for your own words.','Write freely or use a prompt. Nothing here needs to be polished.')+`<div class="hero-grid"><form class="card" id="journal-form"><label for="title">Give this moment a title</label><input id="title" maxlength="160" placeholder="What’s on your mind?"><label for="prompt">A starting point, if you need one</label><select id="prompt"><option value="">Write freely</option><option>What feels difficult, and what do I need?</option><option>What was within my control today?</option><option>When did I feel most like myself?</option><option>What would I say to a friend in my situation?</option></select><label for="writing">Your words</label><textarea id="writing" required maxlength="30000" placeholder="Start wherever you are…"></textarea><div class="actions"><button class="primary">Save entry ↗</button></div></form><div class="card"><p class="eyebrow" style="margin-top:0">A GENTLER WAY TO REFLECT</p><h2>Curiosity over judgment.</h2><p class="small">Try noticing what happened, what you felt, and what you needed. You don’t have to find a lesson in every experience.</p><div class="notice">If writing makes you feel worse or keeps you stuck in a loop, pause. You can look around the room, move gently, or connect with someone.</div><p class="small">Storage: ${state.persist?'Saved in this browser until you delete it.':'This tab only; closing or refreshing loses unsaved-to-device data.'} <a href="#settings">Manage privacy</a></p></div></div><div class="section-head"><h2>Your pages</h2><span class="small">${state.entries.length} entries</span></div>${state.entries.length?state.entries.slice().reverse().map(e=>`<article class="card entry"><time>${new Date(e.date).toLocaleString()}</time><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p><button class="secondary" data-delete-entry="${esc(e.id)}">Delete entry</button></article>`).join(''):'<div class="empty">Your words will find a home here.</div>'}`;}
function progress(){const recent=state.moods.slice(-10);return heading('LOOKING BACK','Notice the bigger picture.','Your check-ins are observations, not a diagnosis or a measure of your worth.')+`<div class="grid3"><div class="card"><span class="metric">${state.moods.length}</span>moments noticed</div><div class="card"><span class="metric">${state.sessions.length}</span>reflections completed</div><div class="card"><span class="metric">${state.plans.filter(x=>x.done).length}</span>actions reviewed</div></div><section class="card" style="margin-top:22px"><h2>Your recent check-ins</h2>${recent.length?`<div class="bars" role="img" aria-label="Recent mood ratings out of five: ${recent.map(x=>niceDate(x.date)+': '+x.value).join('; ')}">${recent.map(x=>`<div class="bar-column"><span class="small">${x.value}/5</span><div class="bar" style="height:${x.value*22}px"></div><small>${niceDate(x.date)}</small></div>`).join('')}</div><p class="small">1 = very low · 3 = somewhere between · 5 = good. These are your own ratings, not a clinical scale.</p>`:'<div class="empty">Check in from My space to begin noticing changes.</div>'}</section><div class="section-head"><h2>Things you’ve been working on</h2></div>${state.sessions.length?state.sessions.slice().reverse().map(s=>`<div class="card entry"><span class="tag">${niceDate(s.date)}</span><h3>${esc(s.name)}</h3><p>${esc(s.takeaway||'You made time to reflect.')}</p></div>`).join(''):'<div class="empty">Completed reflections will appear here.</div>'}<div class="notice">If distress is persisting, getting worse, or affecting daily life, consider professional support. Aura cannot assess whether you need treatment. <a href="#support">Explore support options</a>.</div>`;}
function plans(){return heading('SMALL STEPS','Something worth making room for.','Choose a manageable action, then come back to see what you learned.')+`<form id="plan-form" class="card narrow"><label for="action">What will you do?</label><input id="action" required maxlength="300" placeholder="e.g. Message a friend to arrange a short walk"><label for="when">When?</label><input id="when" type="date" required><label for="why">Why does it matter to you?</label><input id="why" maxlength="400" placeholder="e.g. I want to make more space for connection"><button class="primary" style="margin-top:22px">Add my small step ↗</button></form><div class="section-head"><h2>Your small steps</h2></div>${state.plans.length?state.plans.map(p=>`<div class="card entry"><h3>${p.done?'✓ ':''}${esc(p.action)}</h3><p class="small">${esc(p.when)} · ${esc(p.why)}</p>${p.done?`<p>${esc(p.review)}</p>`:`<button class="secondary" data-review="${p.id}">Review what happened</button>`}<button class="secondary" data-delete-plan="${p.id}">Remove</button></div>`).join(''):'<div class="empty">No steps planned yet. Start as small as you need.</div>'}`;}
function grounding(){return `<div class="narrow">${heading('COME BACK TO THE PRESENT','Find your feet, gently.','You don’t have to feel calm for this to count. Skip anything that feels uncomfortable.')}<div class="card"><h2>Start by noticing your surroundings.</h2><p>Keep your eyes open if you prefer. Feel the support of the chair or the floor. Notice where you are right now.</p>${[['5','Things you can see','Colours, shapes, light, or an object nearby.'],['4','Things you can feel','Your feet on the floor, the texture of fabric, or a comfortable surface.'],['3','Things you can hear','Nearby or far away. Silence counts too.'],['2','Things you can smell','Or name two familiar smells if that is easier.'],['1','Thing you can taste','Or notice one neutral thing around you.']].map(x=>`<div class="summary-row"><strong>${x[0]} · ${x[1]}</strong>${x[2]}</div>`).join('')}<p style="margin-top:20px">Now look around again. What would be a helpful next step: water, rest, a small task, or contacting someone?</p><div class="actions"><a class="primary" href="#home">Return to my space</a><a class="secondary" href="#support">Human support</a></div></div></div>`;}
function breathing(){return `<div class="narrow">${heading('A SLOWER MOMENT','No need to force it.','Follow this optional rhythm or breathe naturally. Keep your breathing gentle, without holding your breath.')}<div class="card" style="text-align:center"><div class="breath" id="breath-orb" aria-hidden="true">Ready</div><p id="breath-status" role="status">One minute. Breathe in gently for 4 seconds, out for 6.</p><div class="actions" style="justify-content:center"><button class="primary" data-action="breathe">Start / restart</button><button class="secondary" data-action="stop-breathe">Stop</button></div><p class="small" style="margin-top:25px">Stop if you feel dizzy, breathless, or more anxious. Natural breathing or <a href="#ground">external grounding</a> may suit you better.</p></div></div>`;}
function support(){return heading('YOU DON’T HAVE TO DO THIS ALONE','Make room for human support.','Aura is not monitored by a clinician and cannot contact help or respond to emergencies.')+`<div class="support-grid"><section class="card"><p class="eyebrow" style="margin-top:0">IF YOU MAY BE IN IMMEDIATE DANGER</p><h2>Seek urgent help now.</h2><p>Contact your local emergency services or go to the nearest emergency department. If you can, ask someone you trust to stay with you while you get help.</p><p>You can say: “I’m not feeling safe on my own. Can you stay with me and help me get support?”</p><p class="small">This app has no live crisis monitoring. A saved journal entry will not alert anyone.</p></section><section class="card"><p class="eyebrow" style="margin-top:0">WHEN THERAPY FEELS OUT OF REACH</p><h2>There may be other routes.</h2><ul><li>Ask a primary-care doctor about public or community mental-health services.</li><li>Look for university training clinics with supervised care.</li><li>Ask providers about sliding-scale fees or reduced-cost places.</li><li>Check student, workplace, or nonprofit support services.</li><li>Consider a moderated peer-support group alongside other care.</li></ul><p class="small">Availability and quality vary by location. Check credentials, confidentiality, fees, and who provides the care.</p></section></div><div class="card" style="margin-top:22px"><h2>A personal support plan</h2><p class="small">Write down a trusted person, a place where you feel safer, and how to reach local urgent care. Avoid including details you don’t want stored on this device.</p><label for="support-plan">My people and next steps</label><textarea id="support-plan" maxlength="10000">${esc(state.support||'')}</textarea><button class="primary" data-action="save-support" style="margin-top:18px">Save support plan</button></div>`;}
function settings(){return heading('YOUR SPACE, YOUR CHOICES','Privacy should be understandable.','Choose what stays, see what Aura does, and take your information with you.')+`<section class="card narrow"><h2>Where your information lives</h2><p>This version runs its exercises in your browser. Journal text, check-ins, and exercises are not sent to an AI model. The optional chat sends only your conversation to Google Gemini after you opt in. Hosting providers may process normal access logs. Google Fonts receives font requests.</p><p>Default storage is this tab’s memory. Optional browser storage stays on this browser profile, has no cloud sync, and is not encrypted by Aura. Avoid device saving on a shared device. Browser or operating-system backups may retain information.</p><label class="check"><input id="persist" type="checkbox" ${state.persist?'checked':''}> Save my Aura data in this browser</label>${!storageAvailable?'<div class="notice">Browser storage may be unavailable. Export to keep your work.</div>':''}<div class="actions"><button class="secondary" data-action="export">Export my data (JSON)</button><button class="secondary" data-action="clear">Delete all my Aura data</button></div><p class="small">Exported files contain sensitive information in readable form. Store them carefully. Deleting here cannot delete files you exported or device backups.</p></section><section class="card narrow" style="margin-top:22px"><h2>What Aura is—and its limits</h2><p>Aura is an adult self-help workspace using original, structured exercises. It is not therapy, a diagnostic service, or a substitute for professional care. It offers optional AI conversation through Google Gemini. AI replies can be mistaken; this app does not provide clinical monitoring or diagnosis.</p><p>Its prompts draw on CBT, behavioural activation, problem-solving, and acceptance-based skills. This implementation has not undergone clinical review or an effectiveness study. Evidence for a psychological approach does not establish evidence for this product.</p><p>We do not offer medication advice, trauma exposure, or automated diagnoses. Pause any exercise that feels unhelpful, and seek human care when needed.</p><h3>Read about the approaches</h3><p><a href="https://www.nice.org.uk/guidance/ng222/chapter/recommendations" target="_blank" rel="noopener noreferrer">NICE: depression in adults, including guided self-help</a><br><a href="https://www.who.int/publications/i/item/9789240003927" target="_blank" rel="noopener noreferrer">WHO: Doing What Matters in Times of Stress</a></p><p class="small">These sources inform the choice of approaches. They do not endorse Aura. This app uses original prompts rather than reproducing their manuals.</p></section>`;}
function route(){if(breathTimer){clearInterval(breathTimer);breathTimer=null;}const page=location.hash.slice(1)||'home';const screens={home,sessions,tools,journal,progress,plan:plans,ground:grounding,breathe:breathing,support,settings};$('#main').innerHTML=page.startsWith('exercise/')?exercise(page.split('/')[1]):(screens[page]||home)();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page||(page.startsWith('exercise/')&&a.hash==='#sessions')));bindForms();}
function bindForms(){const jf=$('#journal-form');if(jf)jf.onsubmit=e=>{e.preventDefault();const prompt=$('#prompt').value;state.entries.push({id:crypto.randomUUID(),date:stamp(),title:$('#title').value.trim()||'A moment to reflect',text:(prompt?prompt+'\n\n':'')+$('#writing').value});save();route();toast('Your entry is saved'+(state.persist?' in this browser.':' for this tab.'));};const pf=$('#plan-form');if(pf)pf.onsubmit=e=>{e.preventDefault();state.plans.push({id:crypto.randomUUID(),action:$('#action').value,when:$('#when').value,why:$('#why').value,done:false});save();route();toast('One small step planned.');};const persist=$('#persist');if(persist)persist.onchange=()=>{state.persist=persist.checked;if(state.persist)save();else try{localStorage.removeItem(KEY);}catch{}toast(state.persist?'Browser saving enabled.':'Browser copy removed. This tab still holds your work.');};}
document.addEventListener('input',e=>{if(e.target.id==='answer'&&flow)flow.answers[flow.index]=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mood){selectedMood=Number(b.dataset.mood);document.querySelectorAll('.mood').forEach(x=>{const on=x===b;x.classList.toggle('selected',on);x.setAttribute('aria-pressed',String(on));});return;}if(b.dataset.deleteEntry){if(confirm('Delete this journal entry?')){state.entries=state.entries.filter(x=>x.id!==b.dataset.deleteEntry);save();route();}return;}if(b.dataset.deletePlan){if(confirm('Remove this action plan?')){state.plans=state.plans.filter(x=>x.id!==b.dataset.deletePlan);save();route();}return;}if(b.dataset.review){const p=state.plans.find(x=>x.id===b.dataset.review);const review=prompt('What happened? What helped or got in the way? An unfinished action can still teach you something.');if(review!==null){p.done=true;p.review=review;save();route();}return;}switch(b.dataset.action){case'mood':if(!selectedMood){toast('Choose how you feel first.');return;}state.moods.push({date:stamp(),value:selectedMood});save();selectedMood=0;route();toast('A moment noticed. Thank you for checking in.');break;case'next':if(flow.index<flow.answers.length-1)flow.index++;else flow.finished=true;route();break;case'back':flow.index=Math.max(0,flow.index-1);route();break;case'edit':flow.finished=false;flow.index=0;route();break;case'finish':{const ex=exercises.find(x=>x.id===flow.id),date=stamp(),takeaway=$('#takeaway').value;state.sessions.push({id:crypto.randomUUID(),date,name:ex.name,takeaway,answers:flow.answers.slice()});state.entries.push({id:crypto.randomUUID(),date,title:ex.name,text:ex.steps.map((s,i)=>s[0]+'\n'+(flow.answers[i]||'Skipped')).join('\n\n')+'\n\nWhat I want to take with me\n'+takeaway});flow=null;save();location.hash='journal';toast('Reflection saved to your journal.');break;}case'save-support':state.support=$('#support-plan').value;save();toast('Support plan saved'+(state.persist?' in this browser.':' for this tab.'));break;case'breathe':startBreath();break;case'stop-breathe':stopBreath();break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aura-personal-data-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'clear':if(confirm('Permanently remove Aura entries, check-ins, plans, and support notes from this tab and browser? Exported files are unaffected.')){try{localStorage.removeItem(KEY);localStorage.removeItem('aura-welcome-seen-v1');}catch{}state={moods:[],entries:[],sessions:[],plans:[],persist:false};flow=null;selectedMood=0;window.auraDataCleared=true;route();toast('Aura data removed from this tab and browser.');if(window.auraAfterClear)window.auraAfterClear();}break;}});
function stopBreath(){clearInterval(breathTimer);breathTimer=null;const orb=$('#breath-orb');if(orb){orb.classList.remove('running');orb.textContent='Paused';$('#breath-status').textContent='Return to your natural breathing. Take your time.';}}
function startBreath(){clearInterval(breathTimer);breathSeconds=0;const orb=$('#breath-orb');orb.classList.remove('running');void orb.offsetWidth;orb.classList.add('running');orb.textContent='Breathe in';$('#breath-status').textContent='Breathe gently. 60 seconds remaining.';breathTimer=setInterval(()=>{breathSeconds++;orb.textContent=breathSeconds%10<4?'Breathe in':'Breathe out';if(breathSeconds%10===0||breathSeconds%10===4)$('#breath-status').textContent=orb.textContent+' gently. '+(60-breathSeconds)+' seconds remaining.';if(breathSeconds>=60){stopBreath();orb.textContent='Take a moment';$('#breath-status').textContent='One minute complete. Notice what feels right for you now.';}},1000);}
window.addEventListener('hashchange',()=>{route();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});route();
const welcome=$('#welcome');welcome.addEventListener('cancel',e=>e.preventDefault());welcome.querySelector('form').addEventListener('submit',()=>{state.onboarded=true;try{localStorage.setItem('aura-welcome-seen-v1','1');}catch{}save();});let welcomeSeen=state.onboarded;try{welcomeSeen=welcomeSeen||localStorage.getItem('aura-welcome-seen-v1')==='1';}catch{}if(!welcomeSeen)welcome.showModal();
